seen={}
def texts(d):
    out=[]
    m=d.get('message')
    if m:
        c=m.get('content')
        if isinstance(c,str): out.append(c)
        elif isinstance(c,list):
            for b in c:
                if b.get('type')=='text': out.append(b['text'])
