                    body.append(re.sub(r'^\s+[0-9a-f]{8}\| ?','',rows[j])); j+=1
                key=(thread,ts,'\n'.join(body))
                if key not in seen: seen[key]=(i,loc)
                continue
            j+=1
for (th,ts,body),(i,loc) in sorted(seen.items(),key=lambda kv:kv[0][1]):
    if ts>='2026-11-07T23:00':
        print(f'### {ts} | first seen line {i} | thread {th[:8]} | {loc}\n{body}\n')
